    if n == 0:
        return 0
    if (n - 1) % (k - 1) != 0:
        return -1
    INF = 10**18
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + stones[i]
    dp = [[0 if i == j else INF for j in range(n)] for i in range(n)]
    for length in range(2, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1
            best = INF
            # split positions where left part can be merged to a valid number of piles
            for m in range(i, j, k - 1):
                cost = dp[i][m] + dp[m + 1][j]
                if cost < best:
                    best = cost
            dp[i][j] = best
            if (length - 1) % (k - 1) == 0:
                dp[i][j] += prefix[j + 1] - prefix[i]
    return dp[0][n - 1]

